def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_all_nines(s):
        return all((ch == '9' for ch in s))
    if is_all_nines(s):
        return num + 2
    num_list = list(s)

    def make_palindrome(arr):
        n = len(arr)
        for i in range(n // 2):
            arr[-(i + 1)] = arr[i]

    def is_greater(arr1, arr2):
        for a, b in zip(arr1, arr2):
            if a > b:
                return True
            elif a < b:
                return False
        return False
    make_palindrome(num_list)
    if not is_greater(num_list, list(s)):
        n = length
        mid = n // 2
        left = mid - 1
        right = mid + 1 if n % 2 == 1 else mid
        carry = 1
        if n % 2 == 1:
            val = int(num_list[mid]) + carry
            carry = val // 10
            num_list[mid] = str(val % 10)
            right = mid + 1
        else:
            right = mid
        while left >= 0 and carry > 0:
            val = int(num_list[left]) + carry
            carry = val // 10
            num_list[left] = str(val % 10)
            num_list[right] = num_list[left]
            left -= 1
            right += 1
        if carry > 0:
            num_list = ['1'] + ['0'] * (n - 1) + ['1']
        else:
            while left >= 0:
                num_list[right] = num_list[left]
                left -= 1
                right += 1
    return int(''.join(num_list))
