def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    Search x starting from 0 upwards, return the first valid pair found.
    If no solution exists, return (-1, -1).
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else (-1, -1)
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return (-1, -1)
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return (-1, -1)
    max_x = n // a if a > 0 else 0
    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
    return (-1, -1)
```

