def get_total_number_of_sequences(n: int, max_value: int) -> int:
    if n <= 0 or max_value <= 0:
        return 0
    dp = [0] * (max_value + 1)
    for v in range(1, max_value + 1):
        dp[v] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (max_value + 1)
        prefix_sum = [0] * (max_value + 2)
        for i in range(1, max_value + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp[i]
        for v in range(1, max_value + 1):
            limit = v // 2
            if limit >= 1:
                new_dp[v] = prefix_sum[limit] - prefix_sum[0]
            else:
                new_dp[v] = 0
        dp = new_dp
    return sum(dp[1:])
