def dif_Square(value: int) -> bool:
    if not isinstance(value, int):
        return False
    if value == 0:
        return True
    abs_value = abs(value)
    from math import isqrt
    limit = isqrt(abs_value)
    for x in range(1, limit + 1):
        if abs_value % x == 0:
            y = abs_value // x
            for s1, s2 in [(x, y), (y, x)]:
                if (s1 + s2) % 2 == 0 and (s1 - s2) % 2 == 0:
                    a = (s1 + s2) // 2
                    b = (s1 - s2) // 2
                    if a * a - b * b == value:
                        return True
    return False
```

