    """
    Finds the first non-negative integer solution (x, y) to the equation ax + by = n,
    by incrementing x from 0 upward and checking for y.
    Returns a tuple (x, y) if a solution is found, otherwise None.
    """
    if a <= 0 or b <= 0:
        return None
    for x in range(n // a + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return None
