def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            raise ValueError('No solution')
    if a == 0:
        if b == 0:
            raise ValueError('No solution')
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            raise ValueError('No solution')
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            raise ValueError('No solution')
    if a > 0:
        max_x = n // a if n >= 0 else 0
        if max_x < 0:
            max_x = 0
        xs = range(max_x + 1)
    else:
        xs = []
        x = 0
        while True:
            val = n - a * x
            if val < 0:
                break
            xs.append(x)
            x += 1
    for x in xs:
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    raise ValueError('No non-negative integer solution')
```

