def remove_column(data, key_to_remove=None, index_to_remove=None):
    """
    Remove entries from nested data.

    If key_to_remove is given, remove all dictionary entries with that key.
    If index_to_remove is given, remove elements at that index from all lists.

    Args:
        data: Nested data structure (dicts and lists).
        key_to_remove: Key name (string) to remove from dictionaries.
        index_to_remove: Index (int) to remove from lists.

    Returns:
        The nested data with the specified keys or list elements removed.
    """
    if isinstance(data, dict):
        new_dict = {}
        for k, v in data.items():
            if k != key_to_remove:
                new_dict[k] = remove_column(v, key_to_remove, index_to_remove)
        return new_dict
    elif isinstance(data, list):
        new_list = []
        for i, v in enumerate(data):
            if i != index_to_remove:
                new_list.append(remove_column(v, key_to_remove, index_to_remove))
        return new_list
    else:
        return data
```

