def zip_tuples(t1: Tuple[Any, ...], t2: Tuple[Any, ...]) -> Tuple[Tuple[Any, Any], ...]:
    """
    Zips two tuples by pairing elements from t1 with elements from t2.
    If t2 is shorter than t1, cycle through t2 repeatedly until all elements of t1 are processed.
    If t2 is empty and t1 is not empty, raise a ValueError.
