def get_total_number_of_sequences(n, m):
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        prefix = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp[i]
        for x in range(1, m + 1):
            lower = 2 * x
            if lower > m:
                continue
            new_dp[lower] += dp[x]
            if m + 1 < len(new_dp):
                new_dp[m + 1] -= dp[x]
        for i in range(1, m + 1):
            new_dp[i] += new_dp[i - 1]
        dp = new_dp
    return sum(dp[1:m + 1])
