def substract_elements(*args):
    """
    Subtract elements pairwise at corresponding positions across nested collections of the same shape.
    Args:
        *args: Two or more nested collections (lists/tuples) of the same shape.
    Returns:
        A nested collection of the same shape with the elements subtracted in order: args[0] - args[1] - args[2] - ...
    """
    if len(args) < 2:
        raise ValueError('At least two nested collections are required')

    def subtract_recursive(elements):
        if not isinstance(elements[0], (list, tuple)):
            result = elements[0]
            for v in elements[1:]:
                result -= v
            return result
        length = len(elements[0])
        for e in elements[1:]:
            if not isinstance(e, (list, tuple)) or len(e) != length:
                raise ValueError('All nested collections must have the same shape')
        res = []
        for i in range(length):
            ith_elements = tuple((e[i] for e in elements))
            res.append(subtract_recursive(ith_elements))
        return type(elements[0])(res)
    return subtract_recursive(args)
