def find_solution(a: int, b: int, n: int) -> tuple[int, int] | None:
    x = 0
    if a == 0:
        if b == 0:
            return (0, 0) if n == 0 else None
        if n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None
    max_iter = abs(n) + abs(b) + abs(a) + 1
    for x in range(max_iter):
        remainder = n - a * x
        if a > 0 and remainder < 0:
