        return m
    dp_prev = [1] * (m + 1)
    dp_prev[0] = 0
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        prefix_sum = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]
        for x in range(1, m + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix_sum[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:])
