def monotonic(l):
    """Return True is list elements are monotonically increasing or decreasing and return False if there are any duplicate elements. Also, return the sum of the list elements as an integer. 
    For strings: Return True if string characters are in alphabetical order or reverse alphabetical order and return False if there are any duplicate characters. Also, return the sum of the string characters as a string.
    The function should not use any loops or in-built sorting methods.

    If the input list or string is empty, return True and the sum as 0 for lists or an empty string for strings.

    >>> monotonic([1, 2, 4, 20])
    (True, 27)
    >>> monotonic([1, 1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    (True, -5)
    >>> monotonic("abcd")
    (True, "abcd")
    >>> monotonic("abca")
    False
    >>> monotonic("dcba")
    (True, "dcba")
    """
    if not l:
        if isinstance(l, list):
            return (True, 0)
        elif isinstance(l, str):
            return (True, '')

    def has_duplicates(seq):
        if len(seq) <= 1:
            return False
        if seq[0] in seq[1:]:
            return True
        return has_duplicates(seq[1:])
    if has_duplicates(l):
        return False

    def is_increasing(seq):
        if len(seq) <= 1:
            return True
        if seq[0] >= seq[1]:
            return False
        return is_increasing(seq[1:])

    def is_decreasing(seq):
        if len(seq) <= 1:
            return True
        if seq[0] <= seq[1]:
            return False
        return is_decreasing(seq[1:])
    inc = is_increasing(l)
    dec = is_decreasing(l)
    if inc or dec:
        if isinstance(l, list):
            return (True, sum(l))
        elif isinstance(l, str):
            return (True, l)
    else:
        return False
