    if k == 0:
        return []
    arr_values = arr[:]
    selected_values = []
    indexed_arr = list(enumerate(arr))

    def compare(a, b):
        return (a > b) - (a < b)

    def kth_largest(arr, k):

        def partition(left, right, pivot_index):
            pivot_value = arr[pivot_index]
            arr[pivot_index], arr[right] = (arr[right], arr[pivot_index])
            store_index = left
            for i in range(left, right):
                if compare(arr[i], pivot_value) > 0:
                    arr[store_index], arr[i] = (arr[i], arr[store_index])
                    store_index += 1
            arr[right], arr[store_index] = (arr[store_index], arr[right])
            return store_index

        def select(left, right, k_smallest):
            if left == right:
                return arr[left]
            pivot_index = left
            pivot_index = partition(left, right, pivot_index)
            if k_smallest == pivot_index:
                return arr[k_smallest]
            elif k_smallest < pivot_index:
                return select(left, pivot_index - 1, k_smallest)
            else:
                return select(pivot_index + 1, right, k_smallest)
        return select(0, len(arr) - 1, k - 1)
    values = arr[:]
    kth_val = kth_largest(values[:], k)
    count_greater = 0
    for v in arr:
        if compare(v, kth_val) > 0:
            count_greater += 1
    equal_needed = k - count_greater
    result = []
    equal_count = 0
    for v in arr:
        if compare(v, kth_val) > 0:
            result.append(v)
        elif compare(v, kth_val) == 0 and equal_count < equal_needed:
            result.append(v)
            equal_count += 1

    def insertion_sort(lst):
        for i in range(1, len(lst)):
            key = lst[i]
            j = i - 1
            while j >= 0 and compare(lst[j], key) > 0:
                lst[j + 1] = lst[j]
                j -= 1
            lst[j + 1] = key
        return lst
    return insertion_sort(result)
